script:
// Folyamatábra lépésenként: 1 + 2 + … + N összege ciklussal
// Step-by-step flowchart: the sum 1 + 2 + … + N with a loop
stage(1000, 600, "#fbfbf8");
title({hu: "Folyamatábra: összegzés ciklussal", en: "Flowchart: summing with a loop"});
param("N", {hu: "N (a ciklus vége)", en: "N (end of the loop)"}, 1, 10, 5, 1, "");
param("spd", {hu: "Lépés / másodperc", en: "Steps per second"}, 0.5, 5, 1.5, 0.5, "1/s");
toggle("auto", {hu: "Automatikus futás", en: "Run automatically"}, false, {key: "a"});
button({hu: "Következő lépés", en: "Next step"}, () => step(), {key: "n"});
button({hu: "Elölről", en: "From the start"}, reset);
resetOn("N");

// A program változói / the program's variables
let N = 0, i = 0, S = 0;
const out = [];                              // kiírt sorok / printed lines

// A folyamatábra elemei: hely, alak, szöveg, mit csinál (run), hova lép tovább (next)
// Flowchart blocks: position, shape, text, what it does (run), where it goes next (next)
const B = {
  start:  {x: 300, y: 95,  shape: "oval", text: "START", next: "input"},
  input:  {x: 300, y: 165, shape: "io",   text: {hu: "Be: N", en: "Input: N"}, run: () => { N = P.N; }, next: "init"},
  init:   {x: 300, y: 235, shape: "box",  text: "i = 1,  S = 0", run: () => { i = 1; S = 0; }, next: "test"},
  test:   {x: 300, y: 320, shape: "if",   text: "i ≤ N ?", next: () => (i <= N ? "add" : "output")},
  add:    {x: 300, y: 410, shape: "box",  text: "S = S + i", run: () => { S = S + i; }, next: "inc"},
  inc:    {x: 300, y: 485, shape: "box",  text: "i = i + 1", run: () => { i = i + 1; }, next: "test"},
  output: {x: 560, y: 320, shape: "io",   text: {hu: "Ki: S", en: "Output: S"}, run: () => { out.push("S = " + S); }, next: "stop"},
  stop:   {x: 560, y: 410, shape: "oval", text: "STOP", next: null},
};

// Nyilak: honnan, hova, felirat, töréspontok / arrows: from, to, label, bend points
const EDGES = [
  ["start", "input"], ["input", "init"], ["init", "test"],
  ["test", "add", {hu: "igen", en: "yes"}], ["add", "inc"],
  ["inc", "test", "", [[160, 485], [160, 320]]],
  ["test", "output", {hu: "nem", en: "no"}], ["output", "stop"],
];

let cur = "start", prev = null;              // az aktuális és az előző elem / current and previous block
function step() {
  const b = B[cur];
  if (!b.next) return;                       // STOP: vége / the end
  const nxt = typeof b.next === "function" ? b.next() : b.next;
  prev = cur; cur = nxt;
  if (B[cur].run) B[cur].run();              // a blokk utasítása a belépéskor fut / the block runs when entered
}

let acc = 0;                                 // automatikus futás időzítője / auto-run timer
update(dt => {
  if (!P.auto) return;
  acc += dt * P.spd;
  if (acc >= 1) { acc = 0; step(); }
});

// Egy blokk megrajzolása / drawing one block
function drawBlock(b, active) {
  const w = 150, h = 46, st = {fill: active ? "#ffe3b3" : "#fff", stroke: active ? C.orange : C.ink, lw: active ? 4 : 2};
  if (b.shape === "oval") rect(b.x - w / 2, b.y - h / 2, w, h, {...st, radius: h / 2});
  if (b.shape === "box")  rect(b.x - w / 2, b.y - h / 2, w, h, st);
  if (b.shape === "io")   polygon([[b.x - w / 2 + 15, b.y - h / 2], [b.x + w / 2 + 15, b.y - h / 2], [b.x + w / 2 - 15, b.y + h / 2], [b.x - w / 2 - 15, b.y + h / 2]], st);
  if (b.shape === "if")   polygon([[b.x, b.y - 36], [b.x + 85, b.y], [b.x, b.y + 36], [b.x - 85, b.y]], st);
  text(b.text, b.x, b.y, {align: "center", baseline: "middle", size: 18, bold: active});
}

draw(t => {
  // 1) nyilak a blokkok alatt / arrows below the blocks
  for (const [from, to, label, via] of EDGES) {
    const a = B[from], b = B[to], pts = [[a.x, a.y], ...(via || []), [b.x, b.y]];
    const taken = from === prev && to === cur;
    const [px, py] = pts[pts.length - 2];    // az utolsó szakasz eleje / start of the last segment
    const gap = px === b.x ? (b.shape === "if" ? 38 : 25) : 90;   // a nyíl hegye a blokk szélén áll meg / tip stops at the block's edge
    const len = hypot(b.x - px, b.y - py);
    const tip = [b.x - (b.x - px) / len * gap, b.y - (b.y - py) / len * gap];
    const col = taken ? C.orange : C.gray;
    polyline([...pts.slice(0, -1), tip], {stroke: col, lw: taken ? 4 : 2});
    arrow(px + (tip[0] - px) * 0.8, py + (tip[1] - py) * 0.8, tip[0], tip[1], {stroke: col, lw: taken ? 4 : 2});
    if (label) text(label, (a.x + pts[1][0]) / 2 + 14, (a.y + pts[1][1]) / 2 + 4, {size: 15, color: C.gray});
  }
  // 2) blokkok / blocks
  for (const id in B) drawBlock(B[id], id === cur);

  // 3) változók táblája / table of variables
  const tx = 720;
  text({hu: "Változók", en: "Variables"}, tx, 120, {size: 20, bold: true});
  [["N", N], ["i", i], ["S", S]].forEach(([name, v], k) => {
    rect(tx, 140 + k * 50, 200, 40, {fill: "#fff", stroke: C.ink, lw: 1.5});
    text(name + " = " + v, tx + 15, 166 + k * 50, {size: 20});
  });
  text({hu: "Kimenet:", en: "Output:"}, tx, 330, {size: 18, bold: true});
  out.slice(-3).forEach((s, k) => text(s, tx, 360 + k * 28, {size: 18, color: C.blue}));
  text({hu: "N = következő lépés,  A = automatikus", en: "N = next step,  A = automatic"}, tx, 560, {size: 14, color: C.gray});

  show({hu: "Aktuális blokk", en: "Current block"}, tr(B[cur].text));
  show({hu: "Összeg S", en: "Sum S"}, S, "", 0);
  show({hu: "Elvárt eredmény N·(N+1)/2", en: "Expected result N·(N+1)/2"}, P.N * (P.N + 1) / 2, "", 0);
});
